"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["61473"],{443928(n){n.exports=JSON.parse('{"id":9344,"title":"\u5012\u91D1\u5B57\u5854\u4F18\u5316","description":"### \u{1F6A8} \u6DF1\u5EA6\u8BCA\u65AD\uFF08\u57FA\u4E8E2026\u5E74\u8FD0\u52A8\u79D1\u5B66\u89C6\u89D2\uFF09\\n\\n1. **\u201C\u65B0\u624B\u798F\u5229\u671F\u201D\u672A\u7ED3\u675F vs. RPT\u7684\u9AD8\u795E\u7ECF\u95E8\u69DB**\\n    - \u4F60\u5065\u8EAB\u4EC51\u4E2A\u591A\u6708\uFF0C\u5367\u63A855kg\uFF0C\u5C5E\u4E8E\u65B0\u624B\u9636\u6BB5\u3002\u6B64\u65F6\u4F60\u7684**\u795E\u7ECF\u52DF\u96C6\u6548\u7387\uFF08Neural Drive\uFF09**\u8FD8\u672A\u5F00\u53D1\u5B8C\u5168\u3002\\n    - **\u77DB\u76FE\u70B9\uFF1A** RPT\u7684\u6838\u5FC3\u662F\u201C\u7B2C\u4E00\u7EC4\u5373\u5DC5\u5CF0\uFF08\u7EDD\u5BF9\u9AD8\u5F3A\u5EA6\uFF09\u201D\u3002\u65B0\u624B\u901A\u5E38\u65E0\u6CD5\u5728\u7B2C\u4E00\u7EC4\u771F\u6B63\u8C03\u52A8100%\u7684\u529B\u91CF\uFF0C\u5BFC\u81F4\u7B2C\u4E00\u7EC4\u523A\u6FC0\u4E0D\u8DB3\uFF0C\u540E\u7EED\u7EC4\u53C8\u56E0\u4E3A\u75B2\u52B3\u5BFC\u81F4\u52A8\u4F5C\u53D8\u5F62\u3002\\n    - **\u7ED3\u8BBA\uFF1A** \u4F60\u9700\u8981\u7684\u662F**\u201C\u7EBF\u6027\u8FDB\u9636\u201D\u4E0E\u201CRPT\u201D\u7684\u6539\u826F\u6DF7\u5408\u4F53**\uFF0C\u91CD\u70B9\u5728\u4E8E\u52A8\u4F5C\u6A21\u5F0F\u7684\u56FA\u5316\u3002\\n2. **\u6781\u5EA6\u660E\u663E\u7684\u201C\u5DE6\u53F3\u5931\u8861\u201D\u4E0E\u201C\u4F53\u6001\u98CE\u9669\u201D**\\n    - \u7FBD\u6BDB\u7403\u80CC\u666F\u5BFC\u81F4\u4F60\u53F3\u624B\u5F3A\u3001\u5DE6\u624B\u5F31\uFF087.5kg vs 10kg\uFF0C\u5DEE\u8DDD\u5DE8\u5927\uFF09\u3002\u5982\u679C\u7528\u6760\u94C3\uFF08\u5982\u6760\u94C3\u5367\u63A8/\u63A8\u4E3E\uFF09\uFF0C\u5F3A\u4FA7\u4F1A\u75AF\u72C2\u4EE3\u507F\uFF0C\u5F31\u4FA7\u6C38\u8FDC\u8FFD\u4E0D\u4E0A\uFF0C\u4E14\u6781\u6613\u5BFC\u81F4\u810A\u67F1\u4FA7\u5F2F\u6216\u9AD8\u4F4E\u80A9\u3002\\n    - **\u80B1\u9AA8\u524D\u79FB + \u786C\u62C9\u8170\u9178\uFF1A** \u8FD9\u662F\u4E00\u4E2A\u8FDE\u9501\u53CD\u5E94\u3002\u8BF4\u660E\u4F60\u7684**\u80A9\u80DB\u9AA8\u7A33\u5B9A\u6027\uFF08\u524D\u952F\u808C/\u4E2D\u4E0B\u659C\u65B9\u808C\uFF09\u5DEE\uFF0C\u4E14\u6838\u5FC3/\u81C0\u90E8**\u4E0D\u4F1A\u6B63\u786E\u53D1\u529B\uFF0C\u5BFC\u81F4\u8170\u690E\u4EE3\u507F\u3002\\n3. **\u9690\u5F62\u70B8\u5F39\uFF1A\u819D\u76D6\u52B3\u635F + \u75D4\u75AE**\\n    - **\u819D\u76D6\uFF1A** \u7FBD\u6BDB\u7403\u6025\u505C\u6025\u8F6C\u4F24\u819D\u76D6\uFF0C\u6DF1\u8E72\u5FC5\u987B\u6781\u5176\u5C0F\u5FC3\uFF0C\u751A\u81F3\u9700\u8981\u907F\u5F00\u5927\u91CD\u91CF\u6DF1\u8E72\uFF0C\u6539\u7528\u66F4\u53CB\u597D\u7684\u52A8\u4F5C\u3002\\n    - **\u75D4\u75AE\uFF08\u91CD\u8981\uFF09\uFF1A** \u6781\u5176\u4E25\u8083\u7684\u95EE\u9898\u3002\u4F20\u7EDF\u529B\u91CF\u4E3E\u5F3A\u8C03\u7684 **\u74E6\u5C14\u8428\u5C14\u74E6\u547C\u5438\u6CD5\uFF08\u618B\u6C14\u589E\u538B\uFF09** \u4F1A\u6781\u5EA6\u589E\u52A0\u8179\u5185\u538B\uFF0C\u76F4\u63A5\u52A0\u91CD\u75D4\u75AE\u3002\u4F60\u9700\u8981\u7279\u6B8A\u7684\u547C\u5438\u7B56\u7565\uFF08\u7528\u529B\u65F6\u6301\u7EED\u547C\u6C14\uFF09\uFF0C\u8FD9\u610F\u5473\u7740**\u7EDD\u5BF9\u4E0D\u80FD\u505A 1-5RM \u7684\u6781\u9650\u91CD\u91CF**\u3002\\n\\n---\\n\\n### \u{1F680} \u4F60\u7684\u4E13\u5C5E\u201C\u5927\u5E08\u7EA7\u201D\u63D0\u793A\u8BCD (Prompt)\\n\\n\u6211\u5DF2\u7ECF\u4E3A\u4F60\u91CD\u65B0\u7F16\u5199\u4E86\u63D0\u793A\u8BCD\u3002\u4F60\u53EF\u4EE5\u76F4\u63A5\u590D\u5236\u4E0B\u9762\u7684\u5185\u5BB9\u7ED9\u5230\u4EFB\u4F55 AI\uFF08\u6216\u8005\u5C31\u5728\u8FD9\u91CC\u8BA9\u6211\u6267\u884C\uFF09\uFF0C\u5B83\u878D\u5408\u4E86\u7269\u7406\u6CBB\u7597\u3001\u5065\u7F8E\u7F8E\u5B66\u548C2026\u5E74\u7684\u524D\u6CBF\u8BAD\u7EC3\u7406\u8BBA\u3002\\n\\n**\u590D\u5236\u4EE5\u4E0B\u5185\u5BB9\uFF1A**\\n\\n---\\n\\n**Role:** \u4F60\u662F\u4E16\u754C\u9876\u7EA7\u7684\u4F53\u80FD\u6559\u7EC3\uFF08CSCS\u8BA4\u8BC1\uFF09\u517C\u7269\u7406\u6CBB\u7597\u4E13\u5BB6\uFF08DPT\uFF09\uFF0C\u7CBE\u901A\u4EBA\u4F53\u751F\u7269\u529B\u5B66\u4E0E\u81EA\u7136\u5065\u7F8E\uFF08Natural Hypertrophy\uFF09\u7F8E\u5B66\u3002\u4F60\u719F\u6089\u622A\u81F32026\u5E741\u6708\u7684\u6700\u65B0\u8FD0\u52A8\u79D1\u5B66\u6587\u732E\uFF08\u5982\u5173\u4E8E\u957F\u4F4D\u808C\u80A5\u5927\u3001RIR\u81EA\u52A8\u8C03\u8282\u3001\u5355\u4FA7\u8BAD\u7EC3\u5BF9\u4E2D\u67A2\u795E\u7ECF\u7684\u5F71\u54CD\u7B49\uFF09\u3002\\n\\n**User Profile (\u7528\u6237\u753B\u50CF):**\\n\\n- **\u57FA\u7840:** \u7537\uFF0C21\u5C81\uFF0C173cm\uFF0C63kg\uFF0C\u4F53\u810216.5%\uFF0C\u6709\u51E0\u5E74\u7FBD\u6BDB\u7403\u7ECF\u5386\uFF0C\u5065\u8EAB\u7ECF\u9A8C\u7EA62\u4E2A\u6708\uFF08\u65B0\u624B/\u521D\u7EA7\uFF09\u3002\\n- **\u529B\u91CF\u6570\u636E:** \u5367\u63A81RM 50kg\uFF1B\u5DE6\u53F3\u4E0A\u80A2\u529B\u91CF\u5931\u8861\uFF08\u5DE6\u5F31\u53F3\u5F3A\uFF09\uFF1B\u5F15\u4F53\u5411\u4E0A3\u4E2A\u3002\\n- **\u98CE\u9669\u63A7\u5236:**\\n    1. **\u75D4\u75AE:** \u4E25\u7981\u6781\u9AD8\u8179\u5185\u538B\u7684\u618B\u6C14\u8BAD\u7EC3\uFF08Valsalva\uFF09\uFF0C\u4E25\u79811-5RM\u7684\u6781\u9650\u91CD\u91CF\u3002\\n    2. **\u819D\u76D6:** \u7FBD\u6BDB\u7403\u52B3\u635F\u53F2\uFF0C\u9700\u907F\u514D\u8FC7\u5927\u7684\u526A\u5207\u529B\u3002\\n    3. **\u4F53\u6001:** \u80B1\u9AA8\u524D\u79FB\uFF0C\u5706\u80A9\uFF0C\u7ECF\u5E38\u4FA7\u7761\u5BFC\u81F4\u7684\u4E0D\u5BF9\u79F0\u3002\\n- **\u76EE\u6807:** \u964D\u4F53\u8102\u81F313%\uFF0C\u6253\u9020\u201C\u5BBD\u80A9+\u7A84\u8170+\u6E05\u6670\u8179\u808C\u201D\u7684X\u578B\u8EAB\u6750\uFF08Aesthetics\uFF09\u3002\u4F18\u5148\u89E3\u51B3\u5DE6\u53F3\u4E0D\u5E73\u8861\u3002\\n\\n**Task (\u4EFB\u52A1):**\\n\\n\u8BF7\u4E3A\u6211\u6539\u826F\u4E00\u4EFD **\u201C\u6539\u826F\u7248\u5012\u91D1\u5B57\u5854 (Modified RPT) + \u77EB\u6B63\u6027\u808C\u80A5\u5927\u201D** \u7684\u8BAD\u7EC3\u8BA1\u5212\u3002\\n\u5728\u4E0B\u9762\u7684\u8BA1\u5212\u4E0A\u9762\u505A\u4F18\u5316\u8C03\u6574\uFF1A\\n\\n\u89C6\u9891 2\uFF1A\u80A9\u90E8\u8BAD\u7EC3 4 \u4E2A\u52A8\u4F5C\u5C31\u8DB3\u591F\u4E86 \u7EC3\u4E00\u4F11\u4E00\u5012\u91D1\u5B57\u5854\u5B8C\u6574\u80A9\u90E8\u8BAD\u7EC3\u8BA1\u5212\u5206\u4EAB\\n\u7EC3\u80A9\u5176\u5B9E\u975E\u5E38\u5BB9\u6613\uFF0C\u56DB\u4E2A\u52A8\u4F5C\u5C31\u591F\u4E86\u3002\\n\u7B2C\u4E00\u4E2A\u52A8\u4F5C\uFF0C\u7528\u5750\u59FF\u54D1\u94C3\u63A8\u80A9\u6216\u8005\u5B9E\u529B\u63A8\u3002\u5728 531 \u70ED\u8EAB\u540E\uFF0C\u7528\u5012\u91D1\u5B57\u5854\u51B2\u51FB 5-7 \u6B21\u7684\u6700\u5927\u505A\u7EC4\u91CD\u91CF\u3002\u6211\u4E2A\u4EBA\u66F4\u63A8\u8350\u5750\u59FF\u63A8\u80A9\uFF0C\u5B83\u662F\u7EC3\u80A9\u7684\u738B\u724C\u52A8\u4F5C\uFF0C\u5BF9\u80A9\u90E8\u6574\u4F53\u7684\u523A\u6FC0\u66F4\u9AD8\u3002\\n\u7B2C\u4E8C\u4E2A\u52A8\u4F5C\u7528\u4FA7\u5E73\u4E3E\u7EC3\u4E2D\u675F\u3002\\n\u7B2C\u4E09\u4E2A\u52A8\u4F5C\uFF0C\u7528\u53CD\u5411\u8774\u8776\u673A\u98DE\u9E1F\u6216\u8005\u7EF3\u7D22\u9762\u62C9\u7EC3\u540E\u675F\u3002\u8FD9\u4E24\u4E2A\u52A8\u4F5C\u90FD\u662F\u505A 4 \u7EC4\uFF0C8-12 \u6B21\uFF0C\u4E0D\u8981\u76F2\u76EE\u51B2\u91CD\u91CF\uFF0C\u505A\u597D\u79BB\u5FC3\u63A7\u5236\uFF0C\u52A8\u4F5C\u884C\u7A0B\u505A\u5168\u7A0B\u3002\\n\u7B2C\u56DB\u4E2A\u52A8\u4F5C\uFF0C\u7528 3 \u7EC4\u963F\u8BFA\u5FB7\u63A8\u80A9\u6536\u5C3E\u5C31\u53EF\u4EE5\u4E86\u3002\\n\u89C6\u9891 3\uFF1A\u7EC3\u4E00\u4F11\u4E00\u5012\u91D1\u5B57\u5854\u5982\u4F55\u7EC3\u80F8\uFF1F\u5206\u4EAB\u80F8\u808C\u8BAD\u7EC3\u5B8C\u6574\u8BA1\u5212\\n\u80F8\u808C\u662F\u4E0A\u80A2\u8BAD\u7EC3\u4E2D\u6700\u7B80\u5355\u7684\u90E8\u4F4D\u4E86\u3002\\n\u9996\u5148\u7528\u4E94\u4E09\u4E00\u70ED\u8EAB\u6CD5\u505A\u5145\u8DB3\u7684\u70ED\u8EAB\u3002\\n\u4E4B\u540E\u7B2C\u4E00\u4E2A\u52A8\u4F5C\u5E73\u677F\u5367\u63A8\uFF0C\u5C31\u7528\u5012\u91D1\u5B57\u5854\u51B2\u51FB\u4E94\u5230\u4E03\u6B21\u7684\u6700\u5927\u91CD\u91CF\uFF0C\u53EA\u505A\u4E09\u7EC4\uFF0C\u6BCF\u7EC4\u95F4\u9699\u5728\u4E09\u5230\u516B\u5206\u949F\u5DE6\u53F3\uFF0C\u76EE\u6807\u662F\u63D0\u5347\u5B83\u505A\u7EC4\u7684\u529B\u91CF\u3002\\n\u7136\u540E\u662F\u4E09\u5230\u56DB\u4E2A\u8F85\u52A9\u52A8\u4F5C\uFF0C\u4E24\u4E2A\u63A8\u4E00\u4E2A\u98DE\u3002\u63A8\u8350\u54D1\u94C3\u4E0A\u659C\u5367\u63A8\u3001\u53CC\u6760\u81C2\u5C48\u4F38\u548C\u6536\u7F29\u98DE\u9E1F\u3002\\n\u4E4B\u540E\u53EF\u4EE5\u5E26\u4E09\u7EC4\u4E09\u5934\uFF0C\u4F46\u4E5F\u53EF\u4EE5\u4E0D\u7EC3\u3002\u6BCF\u4E2A\u52A8\u4F5C\u4E09\u7EC4\uFF0C\u7EC4\u95F4\u6B47\u4E24\u5230\u4E09\u5206\u949F\u5C31\u8DB3\u591F\u4E86\u3002\u6CE8\u610F\u5F3A\u5EA6\u3001\u79BB\u5FC3\u6536\u7F29\u3001\u52A8\u4F5C\u5F62\u6210\u548C\u63A7\u5236\uFF0C\u603B\u5171\u8BAD\u7EC3\u5728\u6B63\u5F0F\u7EC4\u5341\u4E94\u7EC4\u4EE5\u5185\u3002\\n\u56E0\u4E3A\u81EA\u7136\u5065\u8EAB\u589E\u808C\u7684\u524D\u63D0\u662F\u505A\u7EC4\u529B\u91CF\u63D0\u5347\uFF0C\u800C\u4E0D\u662F\u8BAD\u7EC3\u9891\u7387\u6216\u5BB9\u91CF\u7684\u5806\u79EF\u3002\\n\u89C6\u9891 4\uFF1A\u7EC3\u4E00\u4F11\u4E00\u5012\u91D1\u5B57\u5854\u5982\u4F55\u7EC3\u80CC\uFF1F\u5206\u4EAB\u80CC\u90E8\u8BAD\u7EC3\u5B8C\u6574\u8BA1\u5212\\n\u80CC\u90E8\u8BAD\u7EC3\u6BD4\u5F88\u591A\u4EBA\u60F3\u8C61\u7684\u90FD\u8981\u7B80\u5355\u3002\\n\u9996\u5148\u7528 531 \u70ED\u8EAB\u6CD5\uFF0C\u505A\u597D\u5145\u8DB3\u7684\u70ED\u8EAB\u3002\\n\u7B2C\u4E00\u4E2A\u52A8\u4F5C\u8D1F\u91CD\u5F15\u4F53\uFF0C\u6BD4\u5982\uFF1A\u8D1F\u91CD\u5F15\u4F53 60x5\u219255x7\u219255x5\uFF0C\u7528\u5012\u91D1\u5361\u51B2\u51FB 5-7 \u6B21\u7684\u6700\u5927\u91CD\u91CF\u3002\u5982\u679C\u662F\u65B0\u624B\uFF0C\u53EF\u4EE5\u7528\u8F85\u52A9\u5F15\u4F53\u6216\u8005\u9AD8\u4F4D\u4E0B\u62C9\u66FF\u4EE3\uFF0C\u53EA\u505A 3 \u7EC4\uFF0C\u6BCF\u7EC4\u95F4\u6B47\u5728 3-8 \u5206\u949F\u5DE6\u53F3\u3002\\n\u7136\u540E\u662F 3-4 \u4E2A\u8F85\u52A9\u52A8\u4F5C\uFF0C\u9996\u5148\u63A8\u8350\u6B63\u624B\u6760\u94C3\u5212\u8239\u7EC3\u4E0A\u80CC\u90E8\u808C\u7FA4\uFF0C\u7136\u540E\u7EF3\u7D22\u5212\u8239\u6216\u8005\u53CD\u624B\u6760\u94C3\u5212\u8239\uFF0C\u6700\u540E\u662F\u53CD\u624B\u5F15\u4F53\uFF0C\u65B0\u624B\u4E5F\u53EF\u4EE5\u7528\u53CD\u624B\u9AD8\u4F4D\u4E0B\u62C9\uFF0C\u8001\u624B\u4E5F\u53EF\u4EE5\u8D1F\u91CD\u3002\u6BCF\u4E2A\u52A8\u4F5C 3 \u7EC4 8-12 \u6B21\u3002\\n\u7EC3\u5B8C\u8FD9\u51E0\u4E2A\u52A8\u4F5C\u4E8C\u5934\u4E00\u822C\u5DF2\u7ECF\u523A\u6FC0\u5145\u5206\u4E86\uFF0C\u6240\u4EE5\u53EF\u7EC3\u53EF\u4E0D\u7EC3\u3002\u4E4B\u540E\u53EF\u9009\u7EC3 3 \u7EC4\u4E8C\u5934\u8F85\u52A9\u52A8\u4F5C\uFF0C\u90FD\u8981\u6CE8\u610F\u5F3A\u5EA6\u3001\u79BB\u5FC3\u6536\u7F29\u52A8\u4F5C\u3001\u884C\u7A0B\u548C\u63A7\u5236\u3002\\n\u603B\u5171\u8BAD\u7EC3\u5728\u6B63\u5F0F\u7EC4 15 \u7EC4\u4E4B\u5185\uFF0C\u56E0\u4E3A\u81EA\u7136\u5065\u8EAB\u589E\u808C\u7684\u524D\u63D0\u662F\u505A\u7EC4\u529B\u91CF\u63D0\u5347\uFF0C\u800C\u4E0D\u662F\u8BAD\u7EC3\u9891\u7387\u548C\u5BB9\u91CF\u7684\u5806\u79EF\u3002\\n\u89C6\u9891 5\uFF1A\u7EC3\u4E00\u4F11\u4E00\u5012\u91D1\u5B57\u5854\u817F\u90E8\u548C\u8179\u808C\u8BAD\u7EC3\u5B8C\u6574\u8BA1\u5212\\n\u7EC3\u817F\u548C\u7EC3\u8179\u808C\u5F88\u5BB9\u6613\uFF0C\u4F46\u662F\u7EDD\u5BF9\u4E0D\u8F7B\u677E\u3002\\n\u9996\u5148\u6700\u5173\u952E\u7684\u5C31\u662F\u7B2C\u4E00\u4E2A\u52A8\u4F5C\uFF0C\u7528\u5012\u91D1\u5B57\u5854\u505A\u6DF1\u8E72\u3002\u5728 531 \u5145\u5206\u70ED\u8EAB\u540E\uFF0C\u63D0\u5347 5-7 \u6B21\u7684\u6781\u9650\u505A\u7EC4\u7684\u529B\u91CF\uFF0C\u603B\u5171\u4E09\u7EC4\uFF0C\u7EC4\u95F4\u6B47\u8981\u505A\u5145\u5206\uFF0C\u4E00\u822C 5-8 \u5206\u949F\u3002\u56E0\u4E3A\u81EA\u7136\u5065\u8EAB\u589E\u808C\u7684\u5173\u952E\u5C31\u662F\u505A\u7EC4\u529B\u91CF\u7684\u63D0\u5347\u3002\\n\u7136\u540E\u6BCF\u4E2A\u5927\u808C\u7FA4\u7EC3\u4E00\u4E2A\u8F85\u52A9\u52A8\u4F5C\uFF0C\u548C\u5012\u91D1\u5B57\u5854\u52A8\u4F5C\u4E0D\u540C\uFF0C\u8F85\u52A9\u52A8\u4F5C\u7EC4\u95F4\u6B47\u4E00\u822C\u6BCF\u7EC4 2-3 \u5206\u949F\u5C31\u8DB3\u591F\u4E86\u3002\u6BCF\u4E2A\u52A8\u4F5C 3 \u7EC4 8-12 \u6B21\uFF0C\u505A\u597D\u2460\u79BB\u5FC3\u6536\u7F29\uFF0C\u2461\u52A8\u4F5C\u884C\u7A0B\u548C\u2462\u63A7\u5236\u3002\\n\u9996\u5148\u80A1\u56DB\u63A8\u8350\u5750\u59FF\u817F\u5C48\u4F38\u3002\\n\u7136\u540E\u80C6\u7EF3\u808C\u7FA4\u53EF\u4EE5\u505A\u4FEF\u5367\u817F\u5F2F\u4E3E\uFF0C\u4E5F\u53EF\u4EE5\u7528\u559C\u6B22\u7684\u52A8\u4F5C\u6216\u8005\u7F57\u9A6C\u5C3C\u4E9A\u786C\u62C9\u3002\\n\u81C0\u5927\u808C\u53EF\u4EE5\u505A\u5750\u59FF\u9ACB\u5916\u5C55\u6216\u8005\u81C0\u63A8\u3002\\n\u5C0F\u817F\u6709\u4E24\u4E2A\u808C\u7FA4\uFF0C\u4F46\u662F\u6BCF\u6B21\u8BAD\u7EC3\u7528\u4E00\u4E2A\u52A8\u4F5C\u5C31\u8DB3\u591F\u4E86\u3002\\n\u7136\u540E\u52A0\u4E00\u4E2A\u7EC3\u5C0F\u817F\u7684 3 \u7EC4\u63D0\u8E35\u3002\\n\u6700\u540E\u5E26 3 \u7EC4\u9AD8\u5F3A\u5EA6\u7684\u8179\u808C\u8BAD\u7EC3\u5C31\u8DB3\u591F\u4E86\u3002\\n\u7B2C\u4E00\u4E2A\u52A8\u4F5C\uFF1A\u6DF1\u8E72\uFF1A531 \u70ED\u8EAB\u3002\\n\u6DF1\u8E72\uFF1A3 \u7EC4 (\u5012\u91D1\u5B57\u5854\u52A8\u4F5C\uFF0C5-7 \u6B21\uFF0C\u7EC4\u95F4\u6B47 5~8 \u5206\u949F)\u3002\\n\u8F85\u52A9\u52A8\u4F5C (\u6BCF\u4E2A\u808C\u7FA4\u4E00\u4E2A\u52A8\u4F5C) \u7EC4\u95F4\u6B47 2~3 \u5206\u949F\u3002\\n\\n1. \u80A1\u56DB\u5934\u808C 3 \u7EC4 8~12 \u6B21\u3002\\n2. \u8158\u7EF3\u808C 3 \u7EC4 8~12 \u6B21\u3002\\n3. \u81C0\u5927\u808C 3 \u7EC4 8-12 \u6B21\u3002\\n4. \u5C0F\u817F 3 \u7EC4 8~12 \u6B21 (\u867D\u7136\u662F\u4E24\u4E2A\u808C\u7FA4\u4F46\u4E00\u4E2A\u52A8\u4F5C\u5C31\u8DB3\u591F)\u3002\\n5. \u8179\u808C 3 \u7EC4 8~12 \u6B21\u3002\\n\u603B\u5171\u6B63\u5F0F\u7EC4 18 \u7EC4\uFF0C1-1.5 \u5C0F\u65F6\\n\\n**Constraints & Principles (\u6838\u5FC3\u9650\u5236\u4E0E\u539F\u5219 - \u5FC5\u987B\u4E25\u683C\u9075\u5B88):**\\n\\n1. **\u5B89\u5168\u534F\u8BAE (Safety Protocol):**\\n    - \u7531\u4E8E\u75D4\u75AE\u98CE\u9669\uFF0C\u6240\u6709\u590D\u5408\u52A8\u4F5C\u91C7\u7528 **6-10 RM** \u6216 **8-12 RM** \u533A\u95F4\uFF0C\u7981\u6B62 <6 RM \u7684\u5927\u91CD\u91CF\u3002\u5F3A\u8C03\u201C\u7528\u529B\u65F6\u547C\u6C14\u201D\u7684\u547C\u5438\u8282\u594F\u3002\\n    - \u7531\u4E8E\u8170\u9178\u53F2\uFF0C\u6682\u65F6**\u79FB\u9664\u4F20\u7EDF\u6760\u94C3\u786C\u62C9**\uFF0C\u66FF\u6362\u4E3A\u66F4\u5B89\u5168\u7684\u540E\u94FE\u52A8\u4F5C\uFF08\u5982\u7F57\u9A6C\u5C3C\u4E9A\u786C\u62C9\u6216\u5668\u68B0\u52A8\u4F5C\uFF09\u3002\\n    - \u6DF1\u8E72\u7C7B\u52A8\u4F5C\u9700\u51CF\u5C11\u810A\u67F1\u538B\u529B\uFF0C\u4F18\u5148\u8003\u8651\u5355\u817F\u6216\u5668\u68B0\u3002\\n2. **\u5355\u4FA7\u4F18\u5148\u539F\u5219 (Unilateral Priority):**\\n    - \u4E0A\u80A2\u63A8/\u62C9\u52A8\u4F5C**\u5F3A\u5236\u4F7F\u7528\u54D1\u94C3**\uFF08Dumbbells\uFF09\u4EE3\u66FF\u6760\u94C3\uFF0C\u4EE5\u7EA0\u6B63\u5DE6\u53F3\u808C\u529B\u4E0D\u5E73\u8861\u3002\\n    - \u6267\u884C\u6807\u51C6\uFF1A**\u201C\u4EE5\u5F31\u4FA7\u4E3A\u51C6\u201D**\uFF08\u5DE6\u624B\u505A\u51E0\u4E2A\uFF0C\u53F3\u624B\u5C31\u505A\u51E0\u4E2A\uFF0C\u4E0D\u53EF\u591A\u505A\uFF09\u3002\\n3. **\u4F53\u6001\u77EB\u6B63\u5D4C\u5165 (Posture Integration):**\\n    - \u5728\u70ED\u8EAB\u548C\u7EC4\u95F4\u4F11\u606F\u4E2D\u5D4C\u5165\u9488\u5BF9 **\u80B1\u9AA8\u524D\u79FB** \u548C **\u5706\u80A9** \u7684\u77EB\u6B63\u52A8\u4F5C\uFF08\u5982\u80A9\u5916\u65CB\u3001\u524D\u952F\u808C\u6FC0\u6D3B\uFF09\u3002\\n4. **\u6539\u826F RPT \u903B\u8F91 (Modified RPT for Novice):**\\n    - \u7B2C\u4E00\u7EC4\u4E0D\u8FFD\u6C42\u6781\u9650\u91CD\u91CF\uFF0C\u800C\u8FFD\u6C42 **\u201C\u6280\u672F\u6027\u529B\u7AED\u201D (Technical Failure)**\u3002\\n    - \u91C7\u7528 **\u201C\u53CC\u91CD\u8FDB\u9636\u6CD5 (Double Progression)\u201D** \u7ED3\u5408 RPT\uFF1A\u5148\u52A0\u6B21\u6570\uFF0C\u6B21\u6570\u8FBE\u6807\u540E\u518D\u52A0\u91CD\u91CF\uFF0C\u7EC4\u95F4\u51CF\u91CD10%\u4EE5\u4FDD\u8BC1\u540E\u7EED\u7EC4\u8D28\u91CF\u3002\\n5. **\u79D1\u5B66\u808C\u80A5\u5927:**\\n    - \u5E94\u7528 **\u201C\u957F\u4F4D\u62C9\u4F38 (Lengthened Partials)\u201D** \u7406\u8BBA\uFF0C\u5728\u7279\u5B9A\u52A8\u4F5C\uFF08\u5982\u98DE\u9E1F\u3001\u4E0B\u62C9\uFF09\u4E2D\u5F3A\u8C03\u808C\u8089\u62C9\u957F\u4F4D\u7F6E\u7684\u8D1F\u8377\u3002\\n\\n**Output Requirements (\u8F93\u51FA\u8981\u6C42):**\\n\\n1. **\u5468\u8BA1\u5212\u8868:** \u7EC3\u4E00\u4F11\u4E00\u3002\\n2. **\u52A8\u4F5C\u7EC6\u8282:** \u6807\u660E\u7EC4\u6570\u3001\u6B21\u6570\u3001RIR\uFF08\u4FDD\u7559\u6B21\u6570\uFF09\u3001\u8282\u594F\uFF08Tempo\uFF09\u3002\\n3. **\u5173\u952ECue:** \u9488\u5BF9\u6211\u7684\u98CE\u9669\u70B9\uFF08\u819D\u3001\u8170\u3001\u75D4\u75AE\uFF09\u7ED9\u51FA\u5177\u4F53\u7684\u52A8\u4F5C\u6CE8\u610F\u4E8B\u9879\u3002\\n4. **\u70ED\u8EAB\u6D41\u7A0B:** \u9488\u5BF9\u4F53\u6001\u95EE\u9898\u76845\u5206\u949F\u6781\u7B80\u70ED\u8EAB\u3002\\n\\n---\\n\\n### \u{1F6E0}\uFE0F \u4E3A\u4EC0\u4E48\u8FD9\u6837\u6539\uFF1F\uFF08\u6743\u5A01\u89E3\u8BFB\uFF09\\n\\n1. **\u5173\u4E8E\u75D4\u75AE\u7684\u4FDD\u62A4\uFF1A**\\n    - \u539F\u8BA1\u5212\u7684 4-6 RM \u9700\u8981\u6781\u5176\u5F3A\u70C8\u7684\u8179\u538B\u652F\u6491\uFF0C\u8FD9\u5C31\u50CF\u5728\u8840\u7BA1\u4E0A\u88C5\u4E86\u4E2A\u9AD8\u538B\u6CF5\uFF0C\u5BF9\u4F60\u6709\u6781\u9AD8\u98CE\u9669\u3002\u6539\u5230 **8-12 RM**\uFF0C\u4E0D\u4EC5\u66F4\u9002\u5408\u808C\u80A5\u5927\uFF0C\u5141\u8BB8\u4F60**\u8FB9\u63A8\u8FB9\u5410\u6C14**\uFF0C\u6781\u5927\u964D\u4F4E\u8179\u5185\u538B\u3002\\n2. **\u751A\u81F3\u79FB\u9664\u4E86\u6760\u94C3\u5367\u63A8/\u63A8\u4E3E\uFF1A**\\n    - \u65E2\u7136\u4F60\u8981\u201C\u88F8\u4F53\u7F8E\u611F\u201D\u4E14\u201C\u5DE6\u624B\u6296\u52A8\u201D\uFF0C**\u54D1\u94C3**\u662F\u552F\u4E00\u7684\u6B63\u89E3\u3002\u54D1\u94C3\u80FD\u5F3A\u8FEB\u5F31\u4FA7\u72EC\u7ACB\u5DE5\u4F5C\uFF0C\u8FD8\u80FD\u63D0\u4F9B\u66F4\u5927\u7684\u5173\u8282\u6D3B\u52A8\u5E45\u5EA6\uFF08ROM\uFF09\uFF0C\u5BF9\u80F8\u808C\u548C\u80A9\u8180\u7684\u62C9\u4F38\u611F\uFF08\u957F\u4F4D\u808C\u80A5\u5927\uFF09\u8FDC\u8D85\u6760\u94C3\u3002\\n3. **\u786C\u62C9\u7684\u964D\u7EA7\uFF1A**\\n    - \u4F60\u505A\u786C\u62C9\u8170\u9178\uFF0C\u8BF4\u660E\u4F60\u8FD8\u6CA1\u5B66\u4F1A\u7528\u5C41\u80A1\uFF08\u9ACB\u5173\u8282\uFF09\u53D1\u529B\uFF0C\u6216\u8005\u6838\u5FC3\u592A\u5F31\u3002\u6B64\u65F6\u4E0A\u5927\u91CD\u91CF\u786C\u62C9=\u8170\u690E\u81EA\u6740\u3002\u6211\u4EEC\u5148\u7528 **RDL\uFF08\u7F57\u9A6C\u5C3C\u4E9A\u786C\u62C9\uFF09** \u6216 **\u5C71\u7F8A\u633A\u8EAB** \u628A\u540E\u94FE\u7EC3\u5F3A\uFF0C\u7B49\u8170\u4E0D\u9178\u4E86\u518D\u8FDB\u9636\u3002\\n4. **\u201C\u957F\u4F4D\u62C9\u4F38\u201D (2026\u8D8B\u52BF)\uFF1A**\\n    - \u6700\u65B0\u7684\u7814\u7A76\uFF08\u622A\u81F32026\u5E74\u5047\u8BBE\uFF09\u8D8A\u6765\u8D8A\u5F3A\u8C03\uFF1A**\u808C\u8089\u5728\u88AB\u62C9\u957F\u72B6\u6001\u4E0B\u7684\u53D7\u529B\uFF0C\u5BF9\u589E\u808C\u8D21\u732E\u6700\u5927\u3002** \u6BD4\u5982\u505A\u4FA7\u5E73\u4E3E\u65F6\uFF0C\u5E95\u7AEF\u7684\u542F\u52A8\u4E0D\u4EC5\u8981\u7A33\uFF0C\u751A\u81F3\u53EF\u4EE5\u505A\u534A\u7A0B\uFF1B\u505A\u5212\u8239\u65F6\uFF0C\u653E\u51FA\u53BB\u90A3\u4E00\u4E0B\u8981\u5145\u5206\u62C9\u4F38\u80CC\u808C\u3002","owner":"huidong2737","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:38:54.773Z"}')}}]);